import React, { useState, useEffect, useRef } from "react";

const initialExpenses = [
  {
    id: 1,
    date: "2023-08-10",
    category: "arriendo",
    amount: 1200000,
    paymentMethod: "transferencia",
    description: "Arriendo oficina central",
    receipt: null,
  },
  {
    id: 2,
    date: "2023-08-05",
    category: "servicios",
    amount: 150000,
    paymentMethod: "tarjeta",
    description: "Pago de servicios básicos",
    receipt: null,
  },
];

const defaultCategories = [
  "arriendo",
  "servicios",
  "insumos",
  "sueldos",
  "imprevistos",
];
const defaultPaymentMethods = ["efectivo", "transferencia", "tarjeta"];

function ExpensesPage() {
  // Estados principales
  const [expenses, setExpenses] = useState(() => {
    const stored = localStorage.getItem("expenses");
    return stored ? JSON.parse(stored) : initialExpenses;
  });
  const [categories, setCategories] = useState(() => {
    const stored = localStorage.getItem("expenseCategories");
    return stored ? JSON.parse(stored) : defaultCategories;
  });
  const [form, setForm] = useState({
    date: "",
    category: "",
    amount: "",
    paymentMethod: "",
    description: "",
    receipt: null,
  });
  const [filters, setFilters] = useState({
    dateRange: "",
    category: "",
    paymentMethod: "",
    search: "",
  });
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  const [showCategoryModal, setShowCategoryModal] = useState(false);
  const [newCategory, setNewCategory] = useState("");
  const [showEditModal, setShowEditModal] = useState(false);
  const [editExpense, setEditExpense] = useState(null);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [deleteExpenseId, setDeleteExpenseId] = useState(null);

  // Guardar en localStorage cada vez que cambian los gastos o categorías
  useEffect(() => {
    localStorage.setItem("expenses", JSON.stringify(expenses));
  }, [expenses]);
  useEffect(() => {
    localStorage.setItem("expenseCategories", JSON.stringify(categories));
  }, [categories]);

  // Filtros
  const filteredExpenses = expenses.filter((e) => {
    // Filtro por categoría
    if (filters.category && e.category !== filters.category) return false;
    // Filtro por método de pago
    if (filters.paymentMethod && e.paymentMethod !== filters.paymentMethod) return false;
    // Filtro por búsqueda
    if (filters.search && !(
      e.description?.toLowerCase().includes(filters.search.toLowerCase()) ||
      e.category?.toLowerCase().includes(filters.search.toLowerCase())
    )) return false;
    // Filtro por rango de fechas (YYYY-MM-DD)
    if (filters.dateRange) {
      const [from, to] = filters.dateRange.split(" to ");
      if (from && e.date < from) return false;
      if (to && e.date > to) return false;
    }
    return true;
  });

  // Paginación
  const totalPages = Math.ceil(filteredExpenses.length / itemsPerPage);
  const paginatedExpenses = filteredExpenses.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  // Handlers de formulario
  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "receipt") {
      setForm({ ...form, receipt: files[0] });
    } else {
      setForm({ ...form, [name]: value });
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setExpenses([
      ...expenses,
      {
        ...form,
        id: expenses.length ? Math.max(...expenses.map((e) => e.id)) + 1 : 1,
      },
    ]);
    setForm({
      date: "",
      category: "",
      amount: "",
      paymentMethod: "",
      description: "",
      receipt: null,
    });
    setCurrentPage(1);
  };

  // Filtros
  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters((f) => ({ ...f, [name]: value }));
    setCurrentPage(1);
  };

  // Modal de categoría
  const handleAddCategory = (e) => {
    e.preventDefault();
    if (newCategory && !categories.includes(newCategory.toLowerCase())) {
      setCategories([...categories, newCategory.toLowerCase()]);
    }
    setNewCategory("");
    setShowCategoryModal(false);
  };

  // Editar gasto
  const openEditModal = (expense) => {
    setEditExpense(expense);
    setShowEditModal(true);
  };
  const handleEditChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "receipt") {
      setEditExpense({ ...editExpense, receipt: files[0] });
    } else {
      setEditExpense({ ...editExpense, [name]: value });
    }
  };
  const handleEditSubmit = (e) => {
    e.preventDefault();
    setExpenses((prev) =>
      prev.map((g) => (g.id === editExpense.id ? editExpense : g))
    );
    setShowEditModal(false);
  };

  // Eliminar gasto
  const openDeleteModal = (id) => {
    setDeleteExpenseId(id);
    setShowDeleteModal(true);
  };
  const handleDelete = () => {
    setExpenses((prev) => prev.filter((g) => g.id !== deleteExpenseId));
    setShowDeleteModal(false);
  };

  // Render
  return (
    <div className="container mx-auto px-4 py-6">
      <h1 className="text-2xl font-bold mb-4">Sistema de Control de Gastos</h1>

      {/* Filtros */}
      <section className="bg-white rounded-lg shadow-md p-4 mb-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Rango de fechas</label>
            <input
              type="text"
              name="dateRange"
              value={filters.dateRange}
              onChange={handleFilterChange}
              placeholder="YYYY-MM-DD to YYYY-MM-DD"
              className="w-full rounded-md border-gray-300 shadow-sm px-4 py-2 border"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Categoría</label>
            <select
              name="category"
              value={filters.category}
              onChange={handleFilterChange}
              className="w-full rounded-md border-gray-300 shadow-sm px-4 py-2 border"
            >
              <option value="">Todas</option>
              {categories.map((cat) => (
                <option key={cat} value={cat}>{cat.charAt(0).toUpperCase() + cat.slice(1)}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Método de pago</label>
            <select
              name="paymentMethod"
              value={filters.paymentMethod}
              onChange={handleFilterChange}
              className="w-full rounded-md border-gray-300 shadow-sm px-4 py-2 border"
            >
              <option value="">Todos</option>
              {defaultPaymentMethods.map((m) => (
                <option key={m} value={m}>{m.charAt(0).toUpperCase() + m.slice(1)}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Buscar</label>
            <input
              type="text"
              name="search"
              value={filters.search}
              onChange={handleFilterChange}
              className="w-full rounded-md border-gray-300 shadow-sm px-4 py-2 border"
              placeholder="Descripción o categoría"
            />
          </div>
        </div>
      </section>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Formulario de registro rápido */}
        <section className="bg-white rounded-lg shadow-md p-6 lg:col-span-1">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-bold text-gray-800">Registro Rápido</h2>
            <button
              className="text-indigo-600 hover:underline"
              onClick={() => setShowCategoryModal(true)}
              type="button"
            >
              + Categoría
            </button>
          </div>
          <form onSubmit={handleSubmit} className="space-y-4">
            <input
              type="date"
              name="date"
              value={form.date}
              onChange={handleChange}
              className="w-full border rounded px-3 py-2"
              required
            />
            <select
              name="category"
              value={form.category}
              onChange={handleChange}
              className="w-full border rounded px-3 py-2"
              required
            >
              <option value="">Categoría</option>
              {categories.map((cat) => (
                <option key={cat} value={cat}>{cat.charAt(0).toUpperCase() + cat.slice(1)}</option>
              ))}
            </select>
            <input
              type="number"
              name="amount"
              value={form.amount}
              onChange={handleChange}
              className="w-full border rounded px-3 py-2"
              placeholder="Monto"
              required
            />
            <select
              name="paymentMethod"
              value={form.paymentMethod}
              onChange={handleChange}
              className="w-full border rounded px-3 py-2"
              required
            >
              <option value="">Método de pago</option>
              {defaultPaymentMethods.map((m) => (
                <option key={m} value={m}>{m.charAt(0).toUpperCase() + m.slice(1)}</option>
              ))}
            </select>
            <input
              type="text"
              name="description"
              value={form.description}
              onChange={handleChange}
              className="w-full border rounded px-3 py-2"
              placeholder="Descripción"
            />
            <input
              type="file"
              name="receipt"
              onChange={handleChange}
              className="w-full border rounded px-3 py-2"
              accept="image/*,.pdf"
            />
            <button
              type="submit"
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-2 px-4 rounded"
            >
              Registrar Gasto
            </button>
          </form>
        </section>

        {/* Tabla de gastos */}
        <section className="bg-white rounded-lg shadow-md p-6 lg:col-span-2">
          <h2 className="text-xl font-bold text-gray-800 mb-4">Listado de Gastos</h2>
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead>
                <tr>
                  <th className="px-4 py-2">Fecha</th>
                  <th className="px-4 py-2">Categoría</th>
                  <th className="px-4 py-2">Monto</th>
                  <th className="px-4 py-2">Método</th>
                  <th className="px-4 py-2">Descripción</th>
                  <th className="px-4 py-2">Acciones</th>
                </tr>
              </thead>
              <tbody>
                {paginatedExpenses.map((g) => (
                  <tr key={g.id}>
                    <td className="px-4 py-2">{g.date}</td>
                    <td className="px-4 py-2 capitalize">{g.category}</td>
                    <td className="px-4 py-2">${Number(g.amount).toLocaleString()}</td>
                    <td className="px-4 py-2 capitalize">{g.paymentMethod}</td>
                    <td className="px-4 py-2">{g.description}</td>
                    <td className="px-4 py-2">
                      <button className="text-blue-600 mr-2" onClick={() => openEditModal(g)}>
                        Editar
                      </button>
                      <button className="text-red-600" onClick={() => openDeleteModal(g.id)}>
                        Eliminar
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {/* Paginación */}
          <div className="flex justify-between items-center mt-4">
            <span className="text-sm text-gray-700">
              Mostrando {paginatedExpenses.length} de {filteredExpenses.length} gastos
            </span>
            <div className="flex items-center space-x-2">
              <button
                className="px-3 py-1 bg-gray-200 rounded"
                onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                disabled={currentPage === 1}
              >
                Anterior
              </button>
              <span>Página {currentPage} de {totalPages || 1}</span>
              <button
                className="px-3 py-1 bg-gray-200 rounded"
                onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages || totalPages === 0}
              >
                Siguiente
              </button>
            </div>
          </div>
        </section>
      </div>

      {/* Modal para agregar categoría */}
      {showCategoryModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 max-w-md w-full">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-gray-800">Agregar Nueva Categoría</h3>
              <button className="text-gray-500 hover:text-gray-700" onClick={() => setShowCategoryModal(false)}>
                X
              </button>
            </div>
            <form onSubmit={handleAddCategory}>
              <input
                type="text"
                value={newCategory}
                onChange={(e) => setNewCategory(e.target.value)}
                className="w-full border rounded px-3 py-2 mb-4"
                placeholder="Nombre de la categoría"
                required
              />
              <div className="flex justify-end space-x-2">
                <button type="button" className="px-4 py-2 bg-gray-200 rounded" onClick={() => setShowCategoryModal(false)}>
                  Cancelar
                </button>
                <button type="submit" className="px-4 py-2 bg-indigo-600 text-white rounded">
                  Agregar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal para editar gasto */}
      {showEditModal && editExpense && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 max-w-lg w-full">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-gray-800">Editar Gasto</h3>
              <button className="text-gray-500 hover:text-gray-700" onClick={() => setShowEditModal(false)}>
                X
              </button>
            </div>
            <form onSubmit={handleEditSubmit} className="space-y-4">
              <input
                type="date"
                name="date"
                value={editExpense.date}
                onChange={handleEditChange}
                className="w-full border rounded px-3 py-2"
                required
              />
              <select
                name="category"
                value={editExpense.category}
                onChange={handleEditChange}
                className="w-full border rounded px-3 py-2"
                required
              >
                <option value="">Categoría</option>
                {categories.map((cat) => (
                  <option key={cat} value={cat}>{cat.charAt(0).toUpperCase() + cat.slice(1)}</option>
                ))}
              </select>
              <input
                type="number"
                name="amount"
                value={editExpense.amount}
                onChange={handleEditChange}
                className="w-full border rounded px-3 py-2"
                placeholder="Monto"
                required
              />
              <select
                name="paymentMethod"
                value={editExpense.paymentMethod}
                onChange={handleEditChange}
                className="w-full border rounded px-3 py-2"
                required
              >
                <option value="">Método de pago</option>
                {defaultPaymentMethods.map((m) => (
                  <option key={m} value={m}>{m.charAt(0).toUpperCase() + m.slice(1)}</option>
                ))}
              </select>
              <input
                type="text"
                name="description"
                value={editExpense.description}
                onChange={handleEditChange}
                className="w-full border rounded px-3 py-2"
                placeholder="Descripción"
              />
              <input
                type="file"
                name="receipt"
                onChange={handleEditChange}
                className="w-full border rounded px-3 py-2"
                accept="image/*,.pdf"
              />
              <div className="flex justify-end space-x-2">
                <button type="button" className="px-4 py-2 bg-gray-200 rounded" onClick={() => setShowEditModal(false)}>
                  Cancelar
                </button>
                <button type="submit" className="px-4 py-2 bg-indigo-600 text-white rounded">
                  Guardar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal para eliminar gasto */}
      {showDeleteModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 max-w-md w-full">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-gray-800">Confirmar Eliminación</h3>
              <button className="text-gray-500 hover:text-gray-700" onClick={() => setShowDeleteModal(false)}>
                X
              </button>
            </div>
            <p className="text-gray-600 mb-6">¿Estás seguro de que deseas eliminar este gasto? Esta acción no se puede deshacer.</p>
            <div className="flex justify-end space-x-2">
              <button className="px-4 py-2 bg-gray-200 rounded text-gray-700" onClick={() => setShowDeleteModal(false)}>
                Cancelar
              </button>
              <button className="px-4 py-2 bg-red-600 text-white rounded" onClick={handleDelete}>
                Eliminar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default ExpensesPage;
